/**
 * AI Summary block for the Today page (client component).
 *
 * Renders a structured, short-line AI summary of today's tasks, calendar
 * events and top inbox emails, generated by the Hermes AI provider. The
 * server caches per (date + data hash) for ~15 min so repeated page loads
 * don't re-call the model; the refresh button busts it explicitly.
 */
import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Sparkles, RotateCw } from "lucide-react";
import { Markdown } from "@/components/markdown";
import { TODAY } from "@/data/seed";
import { cn } from "@/lib/utils";

export interface SummaryTask {
  id: string;
  title: string;
  done: boolean;
  dueDate?: string | undefined;
  dueTime?: string | undefined;
  priority?: string | undefined;
}

export interface SummaryEvent {
  id: string;
  title: string;
  date: string;
  start?: string | undefined;
  allDay?: boolean | undefined;
  calendar: string;
}

export interface SummaryEmail {
  id: string;
  from: string;
  subject: string;
  snippet: string;
  unread: boolean;
}

async function fetchSummary(force: boolean): Promise<{ text: string; ai: boolean }> {
  const res = await fetch("/api/today-summary", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ date: TODAY, force }),
  });
  if (!res.ok) throw new Error("summary failed");
  return (await res.json()) as { text: string; ai: boolean };
}

export function AiSummary({
  tasks,
  events,
  emails,
}: {
  tasks: SummaryTask[];
  events: SummaryEvent[];
  emails: SummaryEmail[];
}) {
  const [nonce, setNonce] = useState(0);
  const [busting, setBusting] = useState(false);

  const query = useQuery({
    queryKey: ["today-summary", TODAY, nonce],
    queryFn: () => fetchSummary(nonce > 0),
    staleTime: 10 * 60_000,
    // Summary data comes in as props; keep the key minimal but stable.
    retry: 1,
  });

  const refresh = () => {
    setBusting(true);
    setNonce((n) => n + 1);
    // Give the request a moment to land before clearing the spinner state.
    window.setTimeout(() => setBusting(false), 4000);
  };

  const busy = query.isLoading || busting;
  const text = query.data?.text ?? "";

  // Feed payload is serialised into the request server-side via the store —
  // here we only trigger; the handler recomputes the data-hash itself.
  void tasks;
  void events;
  void emails;

  return (
    <section
      className="mt-4 rounded-[var(--radius-xl)] border border-border bg-card p-5 shadow-[var(--shadow-panel)]"
      aria-label="AI summary"
    >
      <div className="mb-2.5 flex items-center gap-2">
        <Sparkles className="size-4 text-accent-violet" aria-hidden />
        <h2 className="text-[11px] font-bold uppercase tracking-[0.1em] text-muted-foreground">
          AI summary
        </h2>
        <button
          type="button"
          onClick={refresh}
          disabled={busy}
          aria-label="Refresh AI summary"
          className="tap ml-auto grid size-7 place-items-center rounded-full border border-border bg-card text-muted-foreground transition-colors hover:bg-surface-2 hover:text-foreground disabled:opacity-50"
        >
          <RotateCw className={cn("size-3.5", busy && "animate-spin")} aria-hidden />
        </button>
      </div>
      {query.isLoading ? (
        <div className="space-y-2">
          <div className="h-3 w-3/4 animate-pulse rounded bg-surface-2" />
          <div className="h-3 w-2/3 animate-pulse rounded bg-surface-2" />
          <div className="h-3 w-1/2 animate-pulse rounded bg-surface-2" />
        </div>
      ) : query.isError ? (
        <p className="text-[13.5px] text-muted-foreground">
          Summary unavailable right now — try the refresh button.
        </p>
      ) : (
        <Markdown
          source={text || "_Nothing to summarise yet._"}
          className="!space-y-1.5 text-[14px] leading-relaxed [&_li]:my-0 [&_ul]:my-0"
        />
      )}
    </section>
  );
}
